def max_sub_array_sum_repeated(nums, k):
    if k <= 0 or not nums:
        return 0

    n = len(nums)
    if k == 1:
        return max(nums)

    # Kadane's algorithm for the original array
    max_ending_here = max_so_far = nums[0]
    for x in nums[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)

    # Compute max prefix sum
    max_prefix_sum = current_sum = nums[0]
    for i in range(1, n):
        current_sum += nums[i]
        max_prefix_sum = max(max_prefix_sum, current_sum)

    # Compute max suffix sum
    max_suffix_sum = current_sum = nums[-1]
    for i in range(n-2, -1, -1):
        current_sum += nums[i]
        max_suffix_sum = max(max_suffix_sum, current_sum)

    # Total sum of the original array
    total_sum = sum(nums)

    # If k > 1, we can potentially use the total sum multiple times
    # The formula derived from the problem logic:
    # We want to maximize the sum of a window of size n in the repeated array.
    # If k >= 2, we can effectively "reuse" the total sum (k-2) times in addition to the prefix and suffix contributions.
    # Specifically, the optimal strategy often involves taking the max prefix, max suffix, and then adding (k-2)*total_sum.
    # However, we must ensure we don't double count or go out of bounds.
    # The logic `max(max_so_far, max_suffix_sum + max_prefix_sum + (k-2)*total_sum)` works for k >= 2.
    # For k=2, it becomes `max_so_far + max_suffix_sum + 0`, which is correct for a window of size n in a 2x array (prefix + suffix covers the whole array).

    if k >= 2:
        return max(max_so_far, max_suffix_sum + max_prefix_sum + (k - 2) * total_sum)
    else:
        return max(max_so_far, max_suffix_sum + max_prefix_sum)

