def toggle_middle_bits(n):
    if n < 4:
        return n  # no middle bits to toggle for numbers with fewer than 3 bits

    msb_pos = n.bit_length() - 1  # position of most significant bit (0-indexed from right)
    lsb_pos = 0  # least significant bit position

    # if MSB and LSB are the same or adjacent, no middle bits
    if msb_pos <= lsb_pos + 1:
        return n

    # Create mask with bits set between MSB and LSB (excluding MSB and LSB)
    mask = 0
    for bit in range(lsb_pos + 1, msb_pos):
        mask |= (1 << bit)

    return n ^ mask

