def get_pairs_count(nums, target_sum):
    from collections import Counter
    count = 0
    freq = Counter(nums)

    # For each unique number, try to find its complement
    for num in list(freq.keys()):
        complement = target_sum - num
        if complement in freq:
            if complement == num:
                # count pairs among freq[num] identical elements: nC2 = n*(n-1)//2
                count += freq[num] * (freq[num] - 1) // 2
            elif complement > num:
                # count pairs between freq[num] and freq[complement]
                count += freq[num] * freq[complement]
    return count

